# s = {1, 2, 3}  Set and dictionary both are use in curly braces but Only dictionary have key and value both and set have only value.
s = {1,2,3,4,5,5,6,8,8,7,} # If we want in ordered format so we use list. If we want unordered and qnique value not duplicate so we can use set.
